type RecordAreaChangeParams struct {
	OrganizationID    uuid.UUID
	AreaID            uuid.UUID
	KnownSeq          int64
	EarliestEventTime pgtype.Timestamptz
	FactKinds         []string
	RecordedAt        time.Time
}

func (q *Queries) RecordAreaChange(ctx context.Context, arg []RecordAreaChangeParams) *RecordAreaChangeBatchResults {
	batch := &pgx.Batch{}
	for _, a := range arg {
		vals := []interface{}{
			a.OrganizationID,
			a.AreaID,
			a.KnownSeq,
			a.EarliestEventTime,
			a.FactKinds,
			a.RecordedAt,
		}
		batch.Queue(recordAreaChange, vals...)
	}
	br := q.db.SendBatch(ctx, batch)
	return &RecordAreaChangeBatchResults{br, len(arg), false}
}

func (b *RecordAreaChangeBatchResults) Exec(f func(int, error)) {
	defer b.br.Close()
	for t := 0; t < b.tot; t++ {
		if b.closed {
			if f != nil {
				f(t, ErrBatchAlreadyClosed)
			}
			continue
		}
		_, err := b.br.Exec()
		if f != nil {
			f(t, err)
		}
	}
}

func (b *RecordAreaChangeBatchResults) Close() error {
	b.closed = true
	return b.br.Close()
}
